result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/options.test.mjs", "content": "import test from "node:test";
import assert from "node:assert/strict";
import { withDefaults, getDefaults } from "./options.mjs";

test("withDefaults does not leak state between calls", () => {
  const a = withDefaults({ retries: 0 });
  assert.equal(a.retries, 0);

  const b = withDefaults({});
  assert.equal(b.retries, 3, "second call should see pristine defaults");

  assert.equal(getDefaults().retries === 3, true);
});

test("mutating returned headers does not affect DEFAULTS", () => {
  const opts = withDefaults({});
  opts.headers.accept = "text/html";
  assert.equal(getDefaults().headers.accept, "application/json");
});

test("unknown extra keys survive the merge", () => {
  const opts = withDefaults({ retries: 1, customFlag: true });
  assert.equal(opts.customFlag, true);
  assert.equal(opts.retries, 1);
});
"})
print(result)

